/// Default dialog labels.
abstract final class M3EDialogStrings {
  /// Close action label.
  static const String close = 'Close';

  /// Dismissive action label.
  static const String cancel = 'Cancel';

  /// Confirming action label.
  static const String confirm = 'OK';

  /// Scrim barrier label.
  static const String dismiss = 'Dismiss';

  /// Full-screen route barrier label.
  static const String fullScreen = 'Full screen dialog';

  /// Discard dialog headline.
  static const String discardTitle = 'Discard unsaved changes?';

  /// Discard dialog keep action.
  static const String keepEditing = 'Keep editing';

  /// Discard dialog confirm action.
  static const String discard = 'Discard';

  /// Semantic hint for a truncated headline.
  static const String expandHeadline = 'Show full headline';
}
